import heapq


def build_order(n, dependencies):
    adj = [[] for _ in range(n)]
    indegree = [0] * n
    for a, b in dependencies:
        adj[a].append(b)
        indegree[b] += 1
    heap = [i for i in range(n) if indegree[i] == 0]
    heapq.heapify(heap)
    order = []
    while heap:
        node = heapq.heappop(heap)
        order.append(node)
        for nxt in adj[node]:
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                heapq.heappush(heap, nxt)
    if len(order) != n:
        return []
    return order
